	open fun deriveFaceGeom() {
		if (this.face_geom!!.size() == this.n_faces().toLong()) {
			return
		}
		this.face_geom!!.assign_ul_T(this.n_faces().toLong(), 0)
		var f: Int = 0
		__L1@ while (f < this.n_faces()) {
			var uf: Long = f.toLong()
			var c: Int = (if (this.face_cl!!.a!![uf.toInt()] >= 0) cpp.RefI.Arr(this.face_cl!!.a, uf.toInt()) else cpp.RefI.Arr(this.face_cr!!.a, uf.toInt()))!!.get()
			this.face_geom!!.a!![uf.toInt()] = if ((c >= 0) && (java.lang.Long.compareUnsigned(c.toLong(), this.cell_geom!!.size()) < 0)) this.cell_geom!!.a!![c.toLong().toInt()] else 0
			f++
		}
	}

	open fun n_chains(): Int {
		return if (this.chain_ptr!!.empty()) 0 else (this.chain_ptr!!.size()).toInt() - 1
	}

	open fun n_cells(): Int {
		return (this.cell_dx!!.size()).toInt()
	}

	open fun n_faces(): Int {
		return (this.face_cl!!.size()).toInt()
	}

	open fun n_nodes(): Int {
		return (this.node_invert!!.size()).toInt()
	}

	open fun n_conduits(): Int {
		return (this.conduit_cell_begin!!.size()).toInt()
	}

